// Gesture Engine
// Event-based segmentation of the gyro stream, same idea as the receiver firmware:
//   WAITING -> movement > start -> ACTIVE -> quiet for QUIET ms -> FINISHED -> COOLDOWN
// Also owns the mode (train / recognize) and the recording session.
//
// In:  {topic:'sample'} from Serial Manager, {topic:'cmd', payload:{cmd,...}} from dashboard
// Out 1: finished gesture -> Dataset & Model
// Out 2: dashboard events (engine, settings)
// Out 3: LCD status line -> Serial Manager

const SETTINGS_FILE = path.join(env.get('GLOVE_DIR'), 'data', 'settings.json');
const DEFAULTS = { start: 0.20, end: 0.12, quiet: 250, minTime: 120, maxTime: 1500, cooldown: 700, preRoll: 3 };
const SENTENCE_DEFAULTS = { start: 0.18, end: 0.11, quiet: 420, minTime: 300, maxTime: 4500, cooldown: 800, preRoll: 3 };

let s = context.get('s');
if (!s) {
    let saved = {};
    try { saved = JSON.parse(fs.readFileSync(SETTINGS_FILE, 'utf8')); } catch (e) { }
    s = {
        settings: Object.assign({}, DEFAULTS, saved.settings || {}),
        mode: saved.mode === 'recognize' ? 'recognize' : 'train',
        recording: false, label: saved.label || 'Hello',
        phase: 'waiting', buf: [], pre: [], startT: 0, quietSince: 0, cooldownUntil: 0,
        bias: saved.bias || { x: 0, y: 0, z: 0 }, biasTick: 0
    };
    context.set('s', s);
    publishFlowState();
}

function save() {
    try {
        fs.writeFileSync(SETTINGS_FILE, JSON.stringify({ settings: s.settings, mode: s.mode, label: s.label, bias: s.bias }, null, 2));
    } catch (e) { node.warn('Cannot save settings: ' + e.message); }
}

function publishFlowState() {
    flow.set('mode', s.mode);
    flow.set('recLabel', s.recording ? s.label : '');
    flow.set('phase', s.phase);
}

function uiState() {
    return {
        topic: 'engine',
        payload: { mode: s.mode, recording: s.recording, label: s.label, phase: s.phase, settings: s.settings, bias: s.bias }
    };
}

function lcdStatus() {
    if (s.mode === 'recognize') return { topic: 'write', payload: 'L,SignSpeaker|Waiting...' };
    if (s.recording) {
        const lbl = s.label || '';
        if (lbl.length <= 11) return { topic: 'write', payload: 'L,Recording:|' + lbl };
        const words = lbl.split(' ');
        let line1 = 'Rec:', line2 = '';
        for (const w of words) {
            if (!line2 && (line1 + ' ' + w).length <= 16) {
                line1 += ' ' + w;
            } else {
                line2 = (line2 ? line2 + ' ' : '') + w;
            }
        }
        return { topic: 'write', payload: 'L,' + line1.substring(0, 16) + '|' + line2.substring(0, 16) };
    }
    return { topic: 'write', payload: 'L,Training mode|Paused' };
}

function setPhase(p) {
    if (s.phase === p) return;
    s.phase = p;
    flow.set('phase', p);
    node.send([null, { topic: 'phase', payload: p }, null]);
}

// The MPU6050 gyro doesn't read zero at rest (this one: X ~ -0.09, Z ~ 0.05 rad/s).
// While waiting with the hand roughly still, track that offset slowly and subtract
// it from every sample, so "still" really means ~0 for the start/end thresholds.
const BIAS_ALPHA = 0.03;

function trackBias(sample, correctedMag) {
    if (s.phase !== 'waiting' || correctedMag >= s.settings.start) return;
    const b = s.bias;
    b.x += BIAS_ALPHA * (sample.gx - b.x);
    b.y += BIAS_ALPHA * (sample.gy - b.y);
    b.z += BIAS_ALPHA * (sample.gz - b.z);
}

function step(sample) {
    const cfg = s.settings;
    const now = isNaN(sample.dev) ? sample.t : sample.dev;
    const b = s.bias;
    const gx = sample.gx - b.x, gy = sample.gy - b.y, gz = sample.gz - b.z;
    const mag = Math.sqrt(gx * gx + gy * gy + gz * gz);
    const row = { time: now, gx, gy, gz };

    trackBias(sample, mag);
    if (++s.biasTick % 25 === 0) {
        node.send([null, { topic: 'bias', payload: { x: +b.x.toFixed(4), y: +b.y.toFixed(4), z: +b.z.toFixed(4) } }, null]);
        if (s.biasTick % 750 === 0) save();
    }

    if (s.phase === 'cooldown' && now >= s.cooldownUntil) setPhase('waiting');

    if (s.phase === 'cooldown') return;

    if (s.phase === 'waiting') {
        s.pre.push(row);
        if (s.pre.length > cfg.preRoll) s.pre.shift();
        if (mag > cfg.start) {
            s.buf = s.pre.slice();
            s.pre = [];
            s.startT = now;
            s.quietSince = 0;
            setPhase('active');
        }
        return;
    }

    // active
    s.buf.push(row);
    if (mag < cfg.end) {
        if (!s.quietSince) s.quietSince = now;
    } else {
        s.quietSince = 0;
    }

    const quietDone = s.quietSince && now - s.quietSince >= cfg.quiet;
    if (!quietDone && now - s.startT < cfg.maxTime) return;

    const endT = quietDone ? s.quietSince : now;
    const duration = endT - s.startT;
    const rows = s.buf.filter(r => r.time <= endT);
    s.buf = [];

    if (duration < cfg.minTime || rows.length < 3) {
        setPhase('waiting');
        node.send([null, { topic: 'discarded', payload: { duration } }, null]);
        return;
    }

    s.cooldownUntil = now + cfg.cooldown;
    setPhase('cooldown');

    const t0 = rows[0].time;
    node.send([{
        topic: 'gesture',
        mode: s.mode,
        recording: s.mode === 'train' && s.recording,
        label: s.label,
        payload: {
            at: Date.now(),
            duration,
            samples: rows.map(r => [r.time - t0, +r.gx.toFixed(4), +r.gy.toFixed(4), +r.gz.toFixed(4)])
        }
    }, null, null]);
}

if (msg.topic === 'sample') {
    step(msg.payload);
    return null;
}

// Receiver (re)booted or simulator started: restore the LCD status screen.
if (msg.topic === 'device') return [null, null, lcdStatus()];

if (msg.topic !== 'cmd') return null;

const c = msg.payload || {};
switch (c.cmd) {
    case 'mode':
        s.mode = c.mode === 'recognize' ? 'recognize' : 'train';
        s.recording = false;
        save();
        break;
    case 'record':
        s.mode = 'train';
        s.recording = true;
        if (c.label) {
            s.label = String(c.label).trim();
            if (s.label.includes(' ') && s.settings.maxTime <= 1500) {
                s.settings.maxTime = SENTENCE_DEFAULTS.maxTime;
                s.settings.quiet = Math.max(s.settings.quiet, SENTENCE_DEFAULTS.quiet);
            }
        }
        save();
        break;
    case 'stop':
        s.recording = false;
        break;
    case 'label':
        if (c.label) {
            s.label = String(c.label).trim();
            if (s.label.includes(' ') && s.settings.maxTime <= 1500) {
                s.settings.maxTime = SENTENCE_DEFAULTS.maxTime;
                s.settings.quiet = Math.max(s.settings.quiet, SENTENCE_DEFAULTS.quiet);
            }
        }
        save();
        break;
    case 'preset':
        if (c.preset === 'sentence') {
            s.settings = Object.assign({}, SENTENCE_DEFAULTS);
        } else {
            s.settings = Object.assign({}, DEFAULTS);
        }
        save();
        break;
    case 'settings': {
        const n = {};
        for (const k of Object.keys(DEFAULTS)) {
            const v = parseFloat((c.settings || {})[k]);
            n[k] = isFinite(v) && v >= 0 ? v : s.settings[k];
        }
        if (n.end > n.start) n.end = n.start;
        s.settings = n;
        save();
        break;
    }
    case 'resetSettings':
        s.settings = Object.assign({}, DEFAULTS);
        save();
        break;
    case 'status':
        break;
    default:
        return null;
}

publishFlowState();
return [null, uiState(), lcdStatus()];

// Dataset & Model
// Stores labelled gesture recordings, trains a k-nearest-neighbour classifier on
// features extracted from them, and classifies every new gesture.
// Before a model is trained, the original rule-based thresholds are used.
//
// Files: data/dataset.json (raw recordings), data/model.json (trained model)
//
// In:  {topic:'gesture'} from Gesture Engine, {topic:'cmd'} from dashboard
// Out 1: dashboard events   Out 2: prediction -> Output   Out 3: LCD status -> Serial

const DATA = path.join(env.get('GLOVE_DIR'), 'data');
const DATASET_FILE = path.join(DATA, 'dataset.json');
const MODEL_FILE = path.join(DATA, 'model.json');
const DEFAULT_LABELS = ['Hello', 'I am', 'Reem', 'Thanks', 'Hello Reem', 'I am Reem', 'Thank you'];
const TRAJ_POINTS = 16;
const K = 3;

function load(file, def) {
    try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { return def; }
}

function saveJson(file, obj) {
    const tmp = file + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(obj));
    fs.renameSync(tmp, file);
}

let st = context.get('st');
if (!st) {
    const ds = load(DATASET_FILE, null) || { labels: DEFAULT_LABELS.slice(), samples: [], rev: 0 };
    ds.rev = ds.rev || 0;
    st = { ds, model: load(MODEL_FILE, null) };
    context.set('st', st);
}
const ds = st.ds;

function saveDataset() {
    ds.rev++;
    saveJson(DATASET_FILE, ds);
}

// ---------- saved snapshots (data/saved/<name>.json = dataset + model) ----------

const SAVED_DIR = path.join(DATA, 'saved');

function hasUnsavedChanges() {
    if (!ds.saved) return ds.samples.length > 0 || !!st.model;
    return ds.saved.rev !== ds.rev || ds.saved.modelAt !== (st.model ? st.model.trainedAt : 0);
}

function listSaved() {
    try {
        return fs.readdirSync(SAVED_DIR).filter(f => f.endsWith('.json')).map(f => f.slice(0, -5)).sort().reverse();
    } catch (e) { return []; }
}

function saveSnapshot() {
    fs.mkdirSync(SAVED_DIR, { recursive: true });
    const d = new Date();
    const p = n => String(n).padStart(2, '0');
    const name = 'training-' + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + '-' + p(d.getHours()) + p(d.getMinutes()) + p(d.getSeconds());
    ds.saved = { name, at: Date.now(), rev: ds.rev, modelAt: st.model ? st.model.trainedAt : 0 };
    saveJson(path.join(SAVED_DIR, name + '.json'), { dataset: ds, model: st.model });
    saveJson(DATASET_FILE, ds);
    return name;
}

// Replace the working dataset in place (ds is shared with context).
function replaceDataset(next) {
    for (const k of Object.keys(ds)) delete ds[k];
    Object.assign(ds, next);
}

function writeModel() {
    if (st.model) saveJson(MODEL_FILE, st.model);
    else { try { fs.unlinkSync(MODEL_FILE); } catch (e) { } }
}

// ---------- features ----------

// samples: [[tMs, gx, gy, gz], ...]
function features(samples) {
    const n = samples.length;
    const t0 = samples[0][0], t1 = samples[n - 1][0];
    const f = [(t1 - t0) / 1000];

    for (let a = 1; a <= 3; a++) {
        let min = Infinity, max = -Infinity, sum = 0, sumAbs = 0, peak = 0;
        for (const r of samples) {
            const v = r[a];
            if (v < min) min = v;
            if (v > max) max = v;
            sum += v;
            sumAbs += Math.abs(v);
            if (Math.abs(v) > Math.abs(peak)) peak = v;
        }
        const mean = sum / n;
        let varSum = 0;
        for (const r of samples) varSum += (r[a] - mean) * (r[a] - mean);
        f.push(max - min, mean, Math.sqrt(varSum / n), sumAbs / n, peak);
    }

    const mags = samples.map(r => Math.sqrt(r[1] * r[1] + r[2] * r[2] + r[3] * r[3]));
    f.push(mags.reduce((x, y) => x + y, 0) / n, Math.max.apply(null, mags));

    // Shape of the movement over time: each axis resampled to TRAJ_POINTS points.
    for (let a = 1; a <= 3; a++) {
        for (let i = 0; i < TRAJ_POINTS; i++) {
            const t = t0 + (t1 - t0) * i / (TRAJ_POINTS - 1);
            let j = 0;
            while (j < n - 2 && samples[j + 1][0] < t) j++;
            const A = samples[j], B = samples[Math.min(j + 1, n - 1)];
            const span = B[0] - A[0];
            const u = span > 0 ? Math.min(1, Math.max(0, (t - A[0]) / span)) : 0;
            f.push(A[a] + (B[a] - A[a]) * u);
        }
    }
    return f;
}

function ranges(samples) {
    const r = [1, 2, 3].map(a => {
        const v = samples.map(s => s[a]);
        return Math.max.apply(null, v) - Math.min.apply(null, v);
    });
    return { x: r[0], y: r[1], z: r[2] };
}

// Original thresholds from the receiver firmware, used until a model exists.
function classifyRules(samples) {
    const { x, y, z } = ranges(samples);
    let label = 'Unknown';
    if (x > 0.70 && y > 0.40 && z > 0.50) label = 'Hello';
    else if (y > 0.65 && y > x * 1.15 && y > z * 1.15) label = 'I am';
    else if (x < 0.30 && y < 0.30 && z < 0.30) label = 'Reem';
    else if (z > 0.70 && x > 0.25 && z > y) label = 'Thanks';
    return { label, known: label !== 'Unknown', confidence: null, source: 'rules', ranges: { x, y, z } };
}

// ---------- k-NN ----------

function dist(a, b) {
    let s = 0;
    for (let i = 0; i < a.length; i++) s += (a[i] - b[i]) * (a[i] - b[i]);
    return Math.sqrt(s / a.length);
}

function knn(z, points, labels, k, exclude) {
    const d = [];
    for (let i = 0; i < points.length; i++) if (i !== exclude) d.push([dist(z, points[i]), labels[i]]);
    d.sort((a, b) => a[0] - b[0]);
    const top = d.slice(0, Math.min(k, d.length));
    const votes = {};
    let total = 0;
    for (const [dd, l] of top) {
        const w = 1 / (dd + 1e-3);
        votes[l] = (votes[l] || 0) + w;
        total += w;
    }
    let best = null;
    for (const l of Object.keys(votes)) if (best === null || votes[l] > votes[best]) best = l;
    const nearest = top.filter(t => t[1] === best).reduce((m, t) => Math.min(m, t[0]), Infinity);
    const share = {};
    for (const l of Object.keys(votes)) share[l] = +(votes[l] / total).toFixed(3);
    return { label: best, confidence: votes[best] / total, nearest, votes: share };
}

function standardize(f, mean, std) {
    return f.map((v, i) => (v - mean[i]) / std[i]);
}

function classify(samples) {
    const m = st.model;
    if (!m) return classifyRules(samples);
    const z = standardize(features(samples), m.mean, m.std);
    const r = knn(z, m.points, m.y, m.k, -1);
    return {
        label: r.label,
        known: r.nearest <= m.rejectDistance,
        confidence: +r.confidence.toFixed(3),
        distance: +r.nearest.toFixed(3),
        rejectDistance: m.rejectDistance,
        votes: r.votes,
        source: 'model',
        ranges: ranges(samples)
    };
}

function train() {
    const counts = countByLabel();
    const used = ds.labels.filter(l => (counts[l] || 0) >= 3);
    if (used.length < 1) {
        return { error: 'Record at least 3 samples of a word before training (10+ per word recommended).' };
    }
    const items = ds.samples.filter(s => used.includes(s.label) && s.samples.length >= 3);
    const X = items.map(s => features(s.samples));
    const y = items.map(s => s.label);
    const dim = X[0].length;

    const mean = new Array(dim).fill(0), std = new Array(dim).fill(0);
    for (const f of X) f.forEach((v, i) => { mean[i] += v / X.length; });
    for (const f of X) f.forEach((v, i) => { std[i] += (v - mean[i]) * (v - mean[i]) / X.length; });
    for (let i = 0; i < dim; i++) { std[i] = Math.sqrt(std[i]); if (std[i] < 1e-6) std[i] = 1; }
    const Z = X.map(f => standardize(f, mean, std));
    const k = Math.min(K, Z.length - 1);

    // Leave-one-out evaluation.
    const idx = {};
    used.forEach((l, i) => { idx[l] = i; });
    const matrix = used.map(() => used.map(() => 0));
    let correct = 0;
    const sameClassNearest = [];
    for (let i = 0; i < Z.length; i++) {
        const r = knn(Z[i], Z, y, k, i);
        matrix[idx[y[i]]][idx[r.label]]++;
        if (r.label === y[i]) correct++;
        let best = Infinity;
        for (let j = 0; j < Z.length; j++) if (j !== i && y[j] === y[i]) best = Math.min(best, dist(Z[i], Z[j]));
        if (isFinite(best)) sameClassNearest.push(best);
    }
    sameClassNearest.sort((a, b) => a - b);
    const p95 = sameClassNearest[Math.min(sameClassNearest.length - 1, Math.floor(sameClassNearest.length * 0.95))] || 1;

    const perLabel = {};
    used.forEach((l, i) => { perLabel[l] = { n: counts[l], correct: matrix[i][i] }; });

    st.model = {
        version: 1,
        trainedAt: Date.now(),
        datasetRev: ds.rev,
        k,
        labels: used,
        mean, std,
        points: Z.map(z => z.map(v => +v.toFixed(4))),
        y,
        rejectDistance: +(p95 * 1.5).toFixed(4),
        accuracy: correct / Z.length,
        perLabel,
        confusion: { labels: used, matrix },
        featureCount: dim
    };
    saveJson(MODEL_FILE, st.model);
    return { ok: true };
}

// ---------- dashboard events ----------

function countByLabel() {
    const c = {};
    for (const s of ds.samples) c[s.label] = (c[s.label] || 0) + 1;
    return c;
}

function datasetEvent() {
    return {
        topic: 'dataset',
        payload: {
            labels: ds.labels,
            counts: countByLabel(),
            total: ds.samples.length,
            file: DATASET_FILE,
            saved: ds.saved || null,
            unsaved: hasUnsavedChanges(),
            savedList: listSaved(),
            samples: ds.samples.map(s => ({ id: s.id, label: s.label, at: s.at, duration: s.duration })).reverse()
        }
    };
}

function modelEvent() {
    const m = st.model;
    if (!m) return { topic: 'model', payload: null };
    return {
        topic: 'model',
        payload: {
            trainedAt: m.trainedAt, k: m.k, labels: m.labels, accuracy: m.accuracy,
            perLabel: m.perLabel, confusion: m.confusion, n: m.y.length,
            rejectDistance: m.rejectDistance, stale: m.datasetRev !== ds.rev, file: MODEL_FILE
        }
    };
}

function toast(text, level) {
    return { topic: 'toast', payload: { text, level: level || 'info' } };
}

function cleanLabel(l) {
    return String(l || '').replace(/[\r\n|,]/g, ' ').replace(/\s+/g, ' ').trim().substring(0, 48);
}

// ---------- message handling ----------

if (msg.topic === 'gesture') {
    const g = msg.payload;
    const pred = classify(g.samples);
    const out1 = [];
    let lcd = null;

    if (msg.recording) {
        const sample = {
            id: Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
            label: msg.label, at: g.at, duration: g.duration, samples: g.samples
        };
        if (!ds.labels.includes(sample.label)) ds.labels.push(sample.label);
        ds.samples.push(sample);
        saveDataset();
        const n = countByLabel()[sample.label];
        out1.push(datasetEvent(), modelEvent());
        let l1 = 'Rec: ' + sample.label;
        let l2 = 'Samples: ' + n;
        if (l1.length > 16) {
            const words = sample.label.split(' ');
            l1 = 'Rec:';
            l2 = '';
            for (const w of words) {
                if (!l2 && (l1 + ' ' + w).length <= 16) l1 += ' ' + w;
                else l2 = (l2 ? l2 + ' ' : '') + w;
            }
            if (!l2) l2 = 'Samples: ' + n;
            else l2 = (l2 + ' #' + n).substring(0, 16);
        }
        lcd = { topic: 'write', payload: 'L,' + l1.substring(0, 16) + '|' + l2.substring(0, 16) };
    }

    out1.push({
        topic: 'gesture',
        payload: { at: g.at, duration: g.duration, samples: g.samples, prediction: pred, recorded: !!msg.recording, label: msg.label, mode: msg.mode }
    });

    const out2 = msg.mode === 'recognize' ? { topic: 'prediction', payload: Object.assign({ at: g.at, duration: g.duration }, pred) } : null;
    return [out1, out2, lcd];
}

if (msg.topic !== 'cmd') return null;

const c = msg.payload || {};
switch (c.cmd) {
    case 'train': {
        const r = train();
        if (r.error) return [[toast(r.error, 'error')], null, null];
        const m = st.model;
        const skipped = ds.labels.filter(l => !m.labels.includes(l) && countByLabel()[l]);
        const msgs = [modelEvent(), datasetEvent()];
        if (m.labels.length === 1) {
            msgs.push(toast('Trained on one word ("' + m.labels[0] + '"): the model can only answer "' + m.labels[0] + '" or "Unknown". Record a second word to tell words apart.', 'ok'));
        } else {
            msgs.push(toast('Model trained on ' + m.labels.length + ' words: ' + Math.round(m.accuracy * 100) + '% leave-one-out accuracy on ' + m.y.length + ' samples', 'ok'));
        }
        if (skipped.length) msgs.push(toast('Not included (fewer than 3 samples): ' + skipped.join(', ')));
        return [msgs, null, null];
    }
    case 'deleteModel':
        st.model = null;
        try { fs.unlinkSync(MODEL_FILE); } catch (e) { }
        return [[modelEvent(), datasetEvent(), toast('Model deleted - using the built-in rules again')], null, null];
    case 'deleteSample':
        ds.samples = ds.samples.filter(s => s.id !== c.id);
        saveDataset();
        return [[datasetEvent(), modelEvent()], null, null];
    case 'clearLabel':
        ds.samples = ds.samples.filter(s => s.label !== c.label);
        saveDataset();
        return [[datasetEvent(), modelEvent(), toast('Deleted all samples for ' + c.label)], null, null];
    case 'addLabel': {
        const l = cleanLabel(c.label);
        if (!l) return null;
        if (!ds.labels.includes(l)) ds.labels.push(l);
        saveDataset();
        return [[datasetEvent()], null, null];
    }
    case 'removeLabel':
        ds.labels = ds.labels.filter(l => l !== c.label);
        ds.samples = ds.samples.filter(s => s.label !== c.label);
        saveDataset();
        return [[datasetEvent(), modelEvent(), toast('Removed label ' + c.label)], null, null];
    case 'sampleData': {
        const s = ds.samples.find(x => x.id === c.id);
        if (!s) return null;
        return [[{ topic: 'sampleData', payload: { id: s.id, label: s.label, at: s.at, duration: s.duration, samples: s.samples, prediction: classify(s.samples) } }], null, null];
    }
    case 'saveTraining': {
        const name = saveSnapshot();
        return [[datasetEvent(), toast('Saved ' + ds.samples.length + ' samples' + (st.model ? ' and the trained model' : '') + ' as "' + name + '"', 'ok')], null, null];
    }
    case 'deleteWords': {
        const toDelete = Array.isArray(c.labels) ? c.labels : (c.label ? [c.label] : []);
        const keepLabels = !!c.keepLabels;
        if (!toDelete.length) return null;
        ds.samples = ds.samples.filter(s => !toDelete.includes(s.label));
        if (!keepLabels) {
            ds.labels = ds.labels.filter(l => !toDelete.includes(l));
        }
        saveDataset();
        return [[datasetEvent(), modelEvent(), toast('Deleted ' + toDelete.length + ' word(s)' + (keepLabels ? ' samples' : ''), 'ok')], null, null];
    }
    case 'deleteAll':
        replaceDataset({ labels: DEFAULT_LABELS.slice(), samples: [], rev: ds.rev });
        st.model = null;
        writeModel();
        saveDataset();
        return [[datasetEvent(), modelEvent(), toast('Deleted all recorded words and the trained model')],
            null, { topic: 'write', payload: 'L,Training data|deleted' }];
    case 'restoreSaved': {
        const name = String(c.name || '');
        if (!listSaved().includes(name)) return [[toast('Saved training not found: ' + name, 'error')], null, null];
        const snap = load(path.join(SAVED_DIR, name + '.json'), null);
        if (!snap || !snap.dataset) return [[toast('Could not read ' + name, 'error')], null, null];
        replaceDataset(snap.dataset);
        ds.saved = { name, at: Date.now(), rev: ds.rev, modelAt: snap.model ? snap.model.trainedAt : 0 };
        st.model = snap.model || null;
        writeModel();
        saveJson(DATASET_FILE, ds);
        return [[datasetEvent(), modelEvent(), toast('Restored "' + name + '": ' + ds.samples.length + ' samples' + (st.model ? ' + model' : ''), 'ok')], null, null];
    }
    case 'status':
        return [[datasetEvent(), modelEvent()], null, null];
}
return null;

// Output
// Turns one prediction into the final word and sends that same text to the LCD and
// the laptop speaker, so what is shown and what is spoken always match.
//
// In:  {topic:'prediction'} from Dataset & Model, {topic:'cmd'} from dashboard
// Out 1: LCD line -> Serial Manager   Out 2: text -> Speaker   Out 3: dashboard events

const FILE = path.join(env.get('GLOVE_DIR'), 'data', 'output.json');
const DEFAULTS = { speak: true, lcd: true, minConfidence: 0.55, speakUnknown: false };

let cfg = context.get('cfg');
if (!cfg) {
    let saved = {};
    try { saved = JSON.parse(fs.readFileSync(FILE, 'utf8')); } catch (e) { }
    cfg = Object.assign({}, DEFAULTS, saved);
    context.set('cfg', cfg);
}

function settingsEvent() {
    return { topic: 'outputSettings', payload: cfg };
}

function formatLcd(text) {
    if (text === 'Unknown') return 'W,Unknown';
    if (text.length <= 16) return 'W,' + text;
    const words = text.split(' ');
    let l1 = '', l2 = '';
    for (const w of words) {
        if (!l2 && (l1 ? l1 + ' ' + w : w).length <= 16) {
            l1 = l1 ? l1 + ' ' + w : w;
        } else {
            l2 = l2 ? l2 + ' ' + w : w;
        }
    }
    return 'L,' + l1.substring(0, 16) + '|' + l2.substring(0, 16);
}

if (msg.topic === 'prediction') {
    const p = msg.payload;
    const confident = p.confidence === null || p.confidence >= cfg.minConfidence;
    const text = p.known && confident ? p.label : 'Unknown';
    const isUnknown = text === 'Unknown';

    const lcd = cfg.lcd ? { topic: 'write', payload: formatLcd(text) } : null;
    const speak = cfg.speak && (!isUnknown || cfg.speakUnknown)
        ? { topic: 'say', payload: isUnknown ? 'Unknown gesture' : text } : null;

    const ui = {
        topic: 'output',
        payload: Object.assign({}, p, { text, spoken: !!speak, lcdSent: !!lcd, at: Date.now() })
    };
    return [lcd, speak, ui];
}

if (msg.topic === 'cmd') {
    const c = msg.payload || {};
    if (c.cmd === 'outputSettings') {
        const n = c.settings || {};
        if ('speak' in n) cfg.speak = !!n.speak;
        if ('lcd' in n) cfg.lcd = !!n.lcd;
        if ('speakUnknown' in n) cfg.speakUnknown = !!n.speakUnknown;
        if ('minConfidence' in n) {
            const v = parseFloat(n.minConfidence);
            if (isFinite(v)) cfg.minConfidence = Math.min(1, Math.max(0, v));
        }
        try { fs.writeFileSync(FILE, JSON.stringify(cfg, null, 2)); } catch (e) { }
        return [null, null, settingsEvent()];
    }
    if (c.cmd === 'testOutput') {
        const text = String(c.text || 'Hello').substring(0, 48);
        return [
            cfg.lcd ? { topic: 'write', payload: formatLcd(text) } : null,
            cfg.speak ? { topic: 'say', payload: text } : null,
            { topic: 'output', payload: { text, label: text, known: true, confidence: null, source: 'test', spoken: cfg.speak, lcdSent: cfg.lcd, at: Date.now() } }
        ];
    }
    if (c.cmd === 'status') return [null, null, settingsEvent()];
}
return null;

// Speaker
// Speaks text through the laptop speaker using Windows' built-in speech synthesizer.
// A single PowerShell process is kept running so each word is spoken with no startup delay.
//
// In:  {topic:'say', payload:text} | {topic:'cmd', payload:{cmd:'voice'|'rate'|'status'}}
// Out 1: dashboard events

const SCRIPT = [
    '$ProgressPreference = "SilentlyContinue"',
    'Add-Type -AssemblyName System.Speech',
    '$s = New-Object System.Speech.Synthesis.SpeechSynthesizer',
    '$s.SetOutputToDefaultAudioDevice()',
    '[Console]::InputEncoding = [Text.Encoding]::UTF8',
    '[Console]::Out.WriteLine("VOICES:" + (($s.GetInstalledVoices() | ForEach-Object { $_.VoiceInfo.Name }) -join "|"))',
    '[Console]::Out.WriteLine("VOICE:" + $s.Voice.Name)',
    'while ($true) {',
    '  $line = [Console]::In.ReadLine()',
    '  if ($line -eq $null) { break }',
    '  if ($line.StartsWith("VOICE:")) { try { $s.SelectVoice($line.Substring(6)) } catch {}; [Console]::Out.WriteLine("VOICE:" + $s.Voice.Name); continue }',
    '  if ($line.StartsWith("RATE:")) { $s.Rate = [int]$line.Substring(5); continue }',
    '  $s.SpeakAsyncCancelAll()',
    '  [void]$s.SpeakAsync($line)',
    '}'
].join('\n');

let sp = context.get('sp');
if (!sp || !sp.proc || sp.proc.exitCode !== null) {
    const saved = (sp && sp.cfg) || { voice: '', rate: 0 };
    sp = { proc: null, voices: [], voice: '', cfg: saved, last: '' };
    const encoded = Buffer.from(SCRIPT, 'utf16le').toString('base64');
    const proc = cp.spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-EncodedCommand', encoded], { windowsHide: true });
    proc.stdin.setDefaultEncoding('utf8');
    let buf = '';
    proc.stdout.on('data', d => {
        buf += d.toString();
        let i;
        while ((i = buf.indexOf('\n')) >= 0) {
            const line = buf.substring(0, i).trim();
            buf = buf.substring(i + 1);
            if (line.startsWith('VOICES:')) sp.voices = line.substring(7).split('|').filter(Boolean);
            else if (line.startsWith('VOICE:')) sp.voice = line.substring(6);
            node.send(statusEvent());
        }
    });
    proc.on('error', e => node.warn('Cannot start speech: ' + e.message));
    proc.stdin.on('error', () => { });
    proc.stderr.on('data', d => {
        const text = d.toString().trim();
        if (text && !text.startsWith('#< CLIXML') && !text.startsWith('<Objs')) node.warn('Speech: ' + text);
    });
    proc.on('exit', code => { node.status({ fill: 'red', shape: 'ring', text: 'speech stopped (' + code + ')' }); node.send(statusEvent()); });
    sp.proc = proc;
    context.set('sp', sp);
    if (saved.voice) proc.stdin.write('VOICE:' + saved.voice + '\n');
    if (saved.rate) proc.stdin.write('RATE:' + saved.rate + '\n');
    node.status({ fill: 'green', shape: 'dot', text: 'ready' });
}

function statusEvent() {
    return {
        topic: 'speaker',
        payload: { ready: !!(sp.proc && sp.proc.exitCode === null), voices: sp.voices, voice: sp.voice, rate: sp.cfg.rate, last: sp.last }
    };
}

function send(line) {
    if (sp.proc && sp.proc.exitCode === null) sp.proc.stdin.write(line + '\n');
}

if (msg.topic === 'say') {
    const text = String(msg.payload || '').replace(/[\r\n]/g, ' ').trim();
    if (!text || text.startsWith('VOICE:') || text.startsWith('RATE:')) return null;
    sp.last = text;
    send(text);
    node.status({ fill: 'green', shape: 'dot', text: 'said: ' + text });
    return statusEvent();
}

if (msg.topic === 'cmd') {
    const c = msg.payload || {};
    if (c.cmd === 'voice' && c.voice) { sp.cfg.voice = String(c.voice); send('VOICE:' + sp.cfg.voice); }
    if (c.cmd === 'rate') {
        const r = Math.max(-10, Math.min(10, parseInt(c.rate, 10) || 0));
        sp.cfg.rate = r;
        send('RATE:' + r);
    }
    return statusEvent();
}
return null;

finalize:
const sp = context.get('sp');
if (sp && sp.proc) {
    try { sp.proc.stdin.end(); } catch (e) { }
    try { sp.proc.kill(); } catch (e) { }
}
context.set('sp', undefined);

