// Raw Logger
// Continuously stores every gyro sample to a daily CSV file:
//   data/raw/gyro-YYYY-MM-DD.csv
// Rows are buffered and appended about once per second.
//
// In:  {topic:'sample'} from Serial Manager, {topic:'tick'}, {topic:'cmd', payload:{cmd:'logging'|'status'}}
// Out 1: dashboard events

const DIR = path.join(env.get('GLOVE_DIR'), 'data', 'raw');
const HEADER = 'time_iso,epoch_ms,device_ms,gyro_x,gyro_y,gyro_z,mode,recording_label,phase\n';

let lg = context.get('lg');
if (!lg) {
    lg = { enabled: true, rows: [], file: '', written: 0, lastFlush: Date.now() };
    try { fs.mkdirSync(DIR, { recursive: true }); } catch (e) { }
    context.set('lg', lg);
}

function fileFor(ts) {
    const d = new Date(ts);
    const p = n => String(n).padStart(2, '0');
    return path.join(DIR, 'gyro-' + d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + '.csv');
}

function flush() {
    lg.lastFlush = Date.now();
    if (!lg.rows.length) return;
    const rows = lg.rows;
    lg.rows = [];
    const file = fileFor(Date.now());
    let text = rows.join('\n') + '\n';
    if (!fs.existsSync(file)) text = HEADER + text;
    lg.file = file;
    fs.appendFile(file, text, err => { if (err) node.warn('Log write failed: ' + err.message); });
    lg.written += rows.length;
}

function statusEvent() {
    return { topic: 'logger', payload: { enabled: lg.enabled, file: lg.file || fileFor(Date.now()), written: lg.written } };
}

if (msg.topic === 'sample') {
    if (!lg.enabled) return null;
    const s = msg.payload;
    lg.rows.push([
        new Date(s.t).toISOString(), s.t, isNaN(s.dev) ? '' : s.dev,
        s.gx, s.gy, s.gz,
        flow.get('mode') || '', '"' + String(flow.get('recLabel') || '').replace(/"/g, '') + '"', flow.get('phase') || ''
    ].join(','));
    if (lg.rows.length >= 50 || Date.now() - lg.lastFlush > 1000) flush();
    return null;
}

if (msg.topic === 'tick') {
    flush();
    return statusEvent();
}

if (msg.topic === 'cmd') {
    const c = msg.payload || {};
    if (c.cmd === 'logging') {
        lg.enabled = !!c.enabled;
        flush();
    }
    return statusEvent();
}
return null;

// Dashboard Command Router
// Parses JSON commands arriving from the dashboard websocket and sends each one
// to the node that owns it. {cmd:'hello'} asks every node for its current state.
//
// Out: 1 Serial Manager  2 Gesture Engine  3 Dataset & Model  4 Output  5 Speaker  6 Logger

let c;
try { c = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload; } catch (e) { return null; }
if (!c || !c.cmd) return null;

const cmd = m => ({ topic: 'cmd', payload: m });
const out = [null, null, null, null, null, null];

switch (c.cmd) {
    case 'hello':
        return [
            { topic: 'status' }, cmd({ cmd: 'status' }), cmd({ cmd: 'status' }),
            cmd({ cmd: 'status' }), cmd({ cmd: 'status' }), cmd({ cmd: 'status' })
        ];

    case 'connect': out[0] = { topic: 'connect', payload: { path: c.path } }; break;
    case 'disconnect': out[0] = { topic: 'disconnect' }; break;
    case 'connectMqtt': out[0] = { topic: 'connectMqtt', payload: c }; break;
    case 'disconnectMqtt': out[0] = { topic: 'disconnectMqtt' }; break;
    case 'simAuto': out[0] = { topic: 'simAuto', payload: !!c.enabled }; break;
    case 'simGesture': out[0] = { topic: 'simGesture', payload: c.label }; break;

    case 'mode':
    case 'record':
    case 'stop':
    case 'label':
    case 'preset':
    case 'settings':
    case 'resetSettings':
        out[1] = cmd(c); break;

    case 'train':
    case 'deleteModel':
    case 'deleteSample':
    case 'clearLabel':
    case 'addLabel':
    case 'removeLabel':
    case 'deleteWords':
    case 'sampleData':
    case 'saveTraining':
    case 'deleteAll':
    case 'restoreSaved':
        out[2] = cmd(c); break;

    case 'outputSettings':
    case 'testOutput':
        out[3] = cmd(c); break;

    case 'voice':
    case 'rate':
        out[4] = cmd(c); break;

    case 'logging': out[5] = cmd(c); break;

    default: return null;
}
return out;

// Serialises every dashboard event as {"topic":..., "payload":...} for the websocket.
if (!msg.topic) return null;
return { payload: JSON.stringify({ topic: msg.topic, payload: msg.payload === undefined ? null : msg.payload }) };

// Serves the landing page, dashboard cockpit, and data/image downloads.
//   GET /glove                    -> dashboard/landing.html (Landing page explaining STA x AIO & SignSpeaker)
//   GET /glove/dashboard          -> dashboard/index.html (Live operational cockpit)
//   GET /glove?view=dashboard     -> dashboard/index.html
//   GET /glove/landing            -> dashboard/landing.html
//   GET /glove/data/dataset.json  -> raw training recordings
//   GET /glove/data/dataset.csv   -> same recordings, one row per gyro sample
//   GET /glove/data/model.json    -> trained model
//   GET /glove/images/:file       -> Images/:file (MIME detected via binary magic bytes)

const dir = env.get('GLOVE_DIR');
const file = msg.req.params && msg.req.params.file;
msg.headers = { 'Cache-Control': 'no-store' };

function send(status, type, body) {
    msg.statusCode = status;
    msg.headers['Content-Type'] = type;
    msg.payload = body;
    return msg;
}

try {
    const reqUrl = (msg.req && (msg.req.path || msg.req.url)) || '';
    const query = (msg.req && msg.req.query) || {};

    // Route explicit requests for dashboard or landing
    if (file === 'dashboard' || file === 'cockpit' || file === 'index.html') {
        return send(200, 'text/html; charset=utf-8', fs.readFileSync(path.join(dir, 'dashboard', 'index.html'), 'utf8'));
    }
    if (file === 'landing' || file === 'about' || file === 'landing.html') {
        return send(200, 'text/html; charset=utf-8', fs.readFileSync(path.join(dir, 'dashboard', 'landing.html'), 'utf8'));
    }

    if (!file) {
        const isDashboard = query.view === 'dashboard' || query.app === 'cockpit' ||
                            reqUrl.endsWith('/dashboard') || reqUrl.endsWith('/cockpit');
        const targetHtml = isDashboard ? 'index.html' : 'landing.html';
        return send(200, 'text/html; charset=utf-8', fs.readFileSync(path.join(dir, 'dashboard', targetHtml), 'utf8'));
    }

    if (file === 'dataset.json' || file === 'model.json') {
        msg.headers['Content-Disposition'] = 'attachment; filename="' + file + '"';
        return send(200, 'application/json', fs.readFileSync(path.join(dir, 'data', file), 'utf8'));
    }
    if (file === 'dataset.csv') {
        const ds = JSON.parse(fs.readFileSync(path.join(dir, 'data', 'dataset.json'), 'utf8'));
        const rows = ['sample_id,label,recorded_at,t_ms,gyro_x,gyro_y,gyro_z'];
        for (const s of ds.samples) {
            const at = new Date(s.at).toISOString();
            for (const r of s.samples) rows.push([s.id, '"' + s.label + '"', at, r[0], r[1], r[2], r[3]].join(','));
        }
        msg.headers['Content-Disposition'] = 'attachment; filename="dataset.csv"';
        return send(200, 'text/csv', rows.join('\n') + '\n');
    }

    const decodedFile = decodeURIComponent(file);
    const imgPath = path.join(dir, 'Images', decodedFile);
    if (fs.existsSync(imgPath) && fs.statSync(imgPath).isFile()) {
        const buf = fs.readFileSync(imgPath);
        let mime = 'application/octet-stream';
        if (buf.length >= 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4E && buf[3] === 0x47) {
            mime = 'image/png';
        } else if (buf.length >= 2 && buf[0] === 0xFF && buf[1] === 0xD8) {
            mime = 'image/jpeg';
        } else if (decodedFile.toLowerCase().endsWith('.svg')) {
            mime = 'image/svg+xml';
        }
        msg.headers['Cache-Control'] = 'no-cache, must-revalidate';
        return send(200, mime, buf);
    }
    return send(404, 'text/plain', 'Not found');
} catch (e) {
    return send(404, 'text/plain', 'Not available yet: ' + e.message);
}
